<?php
/**
 * Plate migration contract — static guard for the console pages.
 *
 * Every migrated page must:
 *   - call the shell helpers and nothing from the retired chrome
 *     (assets-2, bc-header.php, bc-footer.php, bc-style.css);
 *   - keep its body byte-for-byte identical to the pre-migration revision,
 *     except for the retired bootstrap JS bundle the shell replaces;
 *   - keep the short-trans.php partial it had.
 *
 * The expected bodies live in plate_bodies.php (generated by plate_capture.py), so this
 * test needs neither git nor a shell. Runs under `php -n` in CI: no tokenizer, no
 * mbstring, no database.
 */

$checks = 0;
function chk($cond, $label) {
    global $checks;
    $checks++;
    if (!$cond) {
        throw new RuntimeException('migration contract: ' . $label);
    }
}

$root = dirname(__DIR__);
$editions = array('DGV7.0-SAAS', 'DGV7.0-NON-SAAS');

// The retired template chrome. No console page may reference these any more.
// bc-style.css stays: it is the live shared stylesheet the print receipts use.
$retired = array('assets-2/', 'bc-header.php', 'bc-footer.php');

// Pages migrated by hand rather than by plate_migrate.py, because their old chrome was
// not the standard pagetitle shape.
$handDone = array(
    'DGV7.0-SAAS/web/ai-budgeting.php', 'DGV7.0-NON-SAAS/web/ai-budgeting.php',
    // §25: AI-Assistant.php became the free Support page in both editions.
    'DGV7.0-SAAS/web/AI-Assistant.php', 'DGV7.0-NON-SAAS/web/AI-Assistant.php', 'DGV7.0-NON-SAAS/web/Pricing.php',
    // No pagetitle block, or a print document with its own action bar.
    'DGV7.0-SAAS/web/APIDocs.php', 'DGV7.0-NON-SAAS/web/APIDocs.php',
    'DGV7.0-SAAS/web/GiftCard.php', 'DGV7.0-NON-SAAS/web/GiftCard.php',
    'DGV7.0-SAAS/web/KYCVerification.php', 'DGV7.0-NON-SAAS/web/KYCVerification.php',
    'DGV7.0-SAAS/web/SiteMap.php', 'DGV7.0-NON-SAAS/web/SiteMap.php',
    'DGV7.0-SAAS/web/ViewBankReceipt.php', 'DGV7.0-NON-SAAS/web/ViewBankReceipt.php',
    'DGV7.0-SAAS/web/ViewCard.php', 'DGV7.0-NON-SAAS/web/ViewCard.php',
    'DGV7.0-SAAS/web/ViewDataBundleCard.php', 'DGV7.0-NON-SAAS/web/ViewDataBundleCard.php',
    'DGV7.0-SAAS/web/ViewElectric.php', 'DGV7.0-NON-SAAS/web/ViewElectric.php',
    'DGV7.0-SAAS/web/ViewNINCard.php', 'DGV7.0-NON-SAAS/web/ViewNINCard.php',
    'DGV7.0-SAAS/web/WebsiteOrderRequest.php', 'DGV7.0-NON-SAAS/web/WebsiteOrderRequest.php',
);

// Pages that intentionally render no console chrome of their own: print targets, raw
// callbacks, partials, and iframe/standalone landings.
$later = array(
    'payhub-success.php', 'guest-payment-complete.php',
    'bc-plate-app.php', 'bc-header.php', 'bc-footer.php', 'short-trans.php',
);

// The retired chrome partials are deleted, not merely unused: the shells own the
// layout now, and the page-level features they injected (AI assistant, referral
// modal, support chat) live in bc_app_widgets() / bc_adm_widgets().
foreach ($editions as $edition) {
    foreach (array('bc-header.php', 'bc-footer.php', 'bc-admin-header.php', 'bc-admin-footer.php',
                   'bc-admin-header-link.php', 'bc-spadmin-header.php', 'bc-spadmin-footer.php',
                   'bc-spadmin-header-link.php') as $partial) {
        chk(!is_file($root . '/' . $edition . '/func/' . $partial), "$edition retired partial func/$partial is deleted");
    }
    $app = file_get_contents($root . '/' . $edition . '/func/bc-plate-app.php');
    chk(strpos($app, 'bc-support-chat-widget.php') !== false, "$edition console shell renders the support chat widget");
    // §25: the VTU-purchase AI widget was retired; free AI + human support chat replaces it.
    chk(strpos($app, 'ai-assistant.js') === false, "$edition console shell no longer injects the retired AI assistant");
    chk(strpos($app, 'bc-support-chat-widget.php') !== false, "$edition console shell injects the support chat widget");
    chk(strpos($app, 'referralModal') !== false, "$edition console shell renders the referral modal");
    $adm = file_get_contents($root . '/' . $edition . '/func/bc-plate-admin.php');
    chk(strpos($adm, 'forcePinModal') !== false, "$edition admin shell renders the forced PIN setup");
    chk(strpos($adm, 'quick_set_pin') !== false, "$edition forced PIN setup keeps its AJAX contract");
}

$before = require __DIR__ . '/plate_bodies.php';

foreach ($editions as $edition) {
    $dir = $root . '/' . $edition . '/web';
    chk(is_dir($dir), "$edition web directory exists");

    foreach (glob($dir . '/*.php') as $path) {
        $name = basename($path);
        $rel = $edition . '/web/' . $name;
        $cur = file_get_contents($path);
        $label = $rel;

        // Not on the shell yet: print targets, raw callbacks, and partials.
        if (in_array($name, $later, true)) continue;

        // Signed-out pages sit on the auth shell, not the app shell.
        if (strpos($cur, 'bc_plate_auth_') !== false) {
            chk(strpos($cur, 'bc_plate_auth_top(') !== false, "$label closes on the auth shell");
            continue;
        }

        // Public browser return is intentionally sessionless and non-authoritative.
        if ($name === 'InvoiceReturn.php') {
            chk(strpos($cur, "header('Cache-Control: no-store');") !== false, "$label is non-cacheable");
            chk(strpos($cur, 'Returning to this page does not confirm payment.') !== false, "$label makes no payment claim");
            foreach (array('$_GET', '$_POST', '$_REQUEST', '$_SESSION', 'bc-config.php', 'mysqli_', 'chargeUser(', 'chargeVendor(') as $token) {
                chk(strpos($cur, $token) === false, "$label has no authority via $token");
            }
            continue;
        }

        // Anything else must be on the app shell. If it is not, it has to be a chrome-less
        // endpoint (AJAX, CLI, webhook) rather than a page somebody forgot.
        if (strpos($cur, 'bc_app_head(') === false) {
            chk(strpos($cur, '<!DOCTYPE') === false && strpos($cur, '<html') === false,
                "$label is neither on the shell nor a chrome-less endpoint");
            continue;
        }

        chk(strpos($cur, 'bc_app_head(') !== false, "$label calls bc_app_head(");
        chk(strpos($cur, 'bc_app_foot(') !== false, "$label calls bc_app_foot(");
        foreach ($retired as $token) {
            chk(strpos($cur, $token) === false, "$label has no retired $token");
        }
        if ($name === 'VirtualCard.php') {
            // The missing-stylesheet bug must not come back: the page links its card CSS.
            chk(strpos($cur, 'fintech-cards.css') !== false, "$label links its card stylesheet");
        }
        // Dashboard.php is exempt (designed on the shell, PR #137 follow-ups).
        // VirtualCard.php is exempt too: redesigned on the shell (see DGV7_FINTECH_UPGRADE.md §17). Its shell
        // migration had left the page outside .pk-app__wrap (a residual pagetitle </div>)
        // and its stylesheet (assets/css/fintech-cards.css) unlinked, so the body had to
        // change to fix the layout. The shell-presence checks above still apply.
        if ($name === 'Dashboard.php' || $name === 'VirtualCard.php') continue;
        // Hub.php is designed on the shell (section landing pages, 2026-11): it has no
        // pre-migration body to preserve.
        if ($name === 'Hub.php') continue;
        // PrintHub.php is redesigned on the shell as the PrintHub matrix (2026-11);
        // its service gates and card links are preserved, the body is not.
        if ($name === 'PrintHub.php') {
            chk(strpos($cur, 'pk-matrix') !== false, "$label renders the PrintHub matrix");
            continue;
        }

        // CryptoHub.php is redesigned on the shell (2026-11): the coin art is
        // sized, and the withdraw / self-help modals the page's JS has always
        // posted to are restored. Its PHP handlers, queries and JS are
        // preserved, so pin the behaviour contract instead of the old body.
        if ($name === 'CryptoHub.php') {
            chk(strpos($cur, 'data-pkx="page-redesign"') !== false, "$label carries the redesign layer");
            chk(strpos($cur, 'coin-icons-row') !== false, "$label keeps the coin icon row");
            // §28: the legacy provider handlers were removed entirely. Every trade
            // action is refused by the provider gate at the top of the page, and no
            // retired-provider function may be called from this page any more.
            chk(strpos($cur, 'crypto_provider_mode') !== false, "$label refuses trade actions through the provider gate");
            chk(strpos($cur, 'getPlisio') === false && strpos($cur, 'createPlisioInvoice') === false && strpos($cur, 'plisioCashOut') === false, "$label calls no retired-provider functions");
            foreach (array('id="depositModal"', 'id="swapModal"', 'id="withdrawModal"', 'id="selfHelpModal"',
                           'id="swapForm"', 'id="withdrawForm"', 'id="withdrawCid"', 'id="syncRef"') as $id) {
                chk(strpos($cur, $id) !== false, "$label renders $id");
            }
            chk(strpos($cur, 'LIMIT 3, 7') !== false, "$label keeps its activity window");
            continue;
        }

        // Pricing.php moved to the two-tier model in §25: Smart/Agent/API columns
        // became Personal/Business (Personal keeps the viewer's legacy discount
        // table), so pin the tier contract instead of the old body.
        if ($name === 'Pricing.php' && strpos($rel, 'DGV7.0-SAAS') === 0) {
            chk(strpos($cur, '<th>Personal (%)</th><th>Business (%)</th>') !== false, "$label shows Personal/Business pricing tiers");
            chk(strpos($cur, 'pricing_personal_is_agent') !== false, "$label keeps legacy Agent discounts inside Personal");
            chk(strpos($cur, '<th>Smart') === false && strpos($cur, '<th>Agent') === false && strpos($cur, '<th>API') === false, "$label drops the retired three-tier titles");
            continue;
        }

        // SendFund.php is redesigned on the shell (2026-11): a fintech hero,
        // step pills and a search-as-you-type bank picker replace the old
        // TomSelect dropdown — its library was never loaded by the shell, so
        // constructing it threw and silently killed bank search AND the
        // account-name resolution wired after it. The transfer contract —
        // POST actions, field ids/names, the resolve/delete/OTP AJAX posts —
        // is the behaviour that must not drift.
        if ($name === 'SendFund.php') {
            chk(strpos($cur, 'data-pkx="page-redesign"') !== false, "$label carries the redesign layer");
            chk(strpos($cur, 'sf-hero') !== false, "$label renders the fintech hero");
            chk(strpos($cur, 'id="bank-search"') !== false, "$label renders the bank search input");
            chk(strpos($cur, 'id="bank-results"') !== false, "$label renders the bank results list");
            chk(strpos($cur, 'SF_BANKS') !== false, "$label ships the bank list for type-ahead");
            foreach (array('name="verify-bank"', 'name="process-transfer"', 'name="initiate-transfer"', 'name="reset-bank"',
                           'id="bank-code"', 'name="bank-code"', 'id="account-number"', 'id="resolved-account-name"',
                           "'resolve_account'", "'delete_beneficiary'", 'isset($_POST["send_otp"])', 'fillBeneficiary', 'deleteBeneficiary',
                           'data-feature-otp="withdrawal"', 'bc-feature-email-otp.js', "bc_feature_email_otp(\$get_logged_user_details,'withdrawal')", 'handleTransferSubmit', 'sas_withdrawal_beneficiaries') as $token) {
                chk(strpos($cur, $token) !== false, "$label keeps $token");
            }
            chk(strpos($cur, 'TomSelect') === false, "$label no longer depends on the unloaded TomSelect");
            chk(strpos($cur, 'json_encode($sf_result)') !== false, "$label feeds the captured transfer result to its modal");
            continue;
        }

        // Pay Bills pages are redesigned on the shell (2026-11) with their
        // automation restored (the shell loads jsfile/bc-custom-all.js again).
        // Their form contracts — field ids/names, tick*/pick* handlers, plan
        // queries, POST actions — are the behaviour that must not drift.
        $payBills = array(
            'Data.php' => array('tickDataCarrier', 'id="phone-number"', 'id="internet-data-type"', 'id="product-amount"', 'name="buy-data"'),
            'Airtime.php' => array('tickAirtimeCarrier', 'id="phone-number"', 'id="product-amount"', 'name="buy-airtime"'),
            'BulkData.php' => array('tickBulkDataCarrier', 'id="filtered-phone-number"', 'id="phone-numbers-span"', 'name="buy-data"'),
            'BulkAirtime.php' => array('tickBulkAirtimeCarrier', 'id="filtered-phone-number"', 'id="phone-numbers-span"', 'name="buy-airtime"'),
            'Cable.php' => array('tickCableCarrier', 'id="iuc-number"', 'name="verify-cable"', 'name="buy-cable"', 'name="reset-cable"'),
            'Electric.php' => array('tickElectricCarrier', 'pickElectricQty', 'id="meter-number"', 'name="verify-meter"', 'name="buy-electric"'),
            'Betting.php' => array('tickBettingCarrier', 'pickBettingQty', 'id="customer-id"', 'name="verify-customer"', 'name="buy-betting"'),
            'Exam.php' => array('tickExamCarrier', 'pickExamQty', 'id="product-amount"', 'name="buy-exam"'),
        );
        if (isset($payBills[$name])) {
            chk(strpos($cur, 'data-pkx="page-redesign"') !== false, "$label carries the redesign layer");
            chk(strpos($cur, 'pk-bill__head') !== false, "$label renders the bill card head");
            chk(strpos($cur, 'carrier-grid') !== false, "$label keeps the carrier picker");
            foreach ($payBills[$name] as $token) {
                chk(strpos($cur, $token) !== false, "$label keeps $token");
            }
            continue;
        }

        // §25 new services are shell-native pages with no pre-migration body:
        // they must use the shell and record provider requests via the shared helper.
        $newServices = array('ESIM.php', 'Tuition.php', 'POSRequest.php', 'IntlTransfer.php', 'Referral.php');
        if (in_array($name, $newServices, true)) {
            chk(strpos($cur, 'bc_app_sidebar(') !== false, "$label uses the shell sidebar");
            chk(strpos($cur, 'bc-fintech-services.php') !== false, "$label loads the provider service layer");
            continue;
        }

        // Security remediations deliberately replaced these captured handlers.
        // Pin their current boundaries rather than restoring unsafe old snapshots.
        if ($name === 'SecurityQuest.php') {
            foreach (array('bc_app_sidebar(', 'bc_security_question_policy(', 'bc_validate_csrf();', 'bc_csrf_field()', 'name="set-answer"', 'name="submit-answer"', 'name="reset-answer"') as $token) {
                chk(strpos($cur, $token) !== false, "$label keeps security question boundary $token");
            }
            chk(substr_count($cur,'bc_csrf_field()') === substr_count($cur,'<form '), "$label protects every question form");
            continue;
        }
        if ($name === 'BusinessUpgrade.php') {
            chk(strpos($cur, 'bc_app_sidebar(') !== false, "$label uses the shell sidebar");
            foreach (array('bc_validate_csrf();', "bc_is_rate_limited('kyb_submit'", 'bc_fintech_kyb_submit($bc_upgrade_user, $bc_upgrade_vendor, [', 'name="submit_business_kyb"', 'name="kyb_document"', 'is_uploaded_file($tmp)', 'getimagesize($tmp)', "bin2hex(random_bytes(8))") as $token) {
                chk(strpos($cur, $token) !== false, "$label keeps KYB boundary $token");
            }
            chk(strpos($cur, 'UPDATE sas_users') === false, "$label cannot directly promote its user");
            chk(strpos($cur, 'chargeUser(') === false && strpos($cur, 'chargeVendor(') === false, "$label does not charge for Business requests");
            continue;
        }
        if ($name === 'CoinConversion.php') {
            chk(strpos($cur, 'bc_app_sidebar(') !== false, "$label uses the shell sidebar");
            foreach (array('bc-referral-coins.php', "isServiceEnabled('vtu_coins')", 'bc_validate_csrf();', 'bc_coin_conversion_change((int)$vendor_id, $username, $points)', 'name="convert-coins"', 'name="points"', 'SELECT * FROM sas_conversions WHERE vendor_id = ? AND username = ?') as $token) {
                chk(strpos($cur, $token) !== false, "$label keeps atomic conversion boundary $token");
            }
            chk(strpos($cur, 'chargeUser(') === false && strpos($cur, 'updateUserBalance(') === false && strpos($cur, 'UPDATE sas_') === false, "$label cannot bypass the atomic conversion helper");
            chk(strpos($cur, 'bc_validate_csrf();') < strpos($cur, 'bc_coin_conversion_change('), "$label verifies CSRF before conversion");
            continue;
        }

        if ($name === 'LiveRates.php') {
            foreach (array('bc_app_sidebar(', 'bc-mobile-fx.php', 'bc_validate_csrf();', "bc_mobile_live_quote((int)\$get_logged_user_details['vendor_id']", 'bc_csrf_field()', 'This calculator does not exchange or move wallet funds.', 'htmlspecialchars($notice,ENT_QUOTES,') as $token) {
                chk(strpos($cur, $token) !== false, "$label keeps indicative FX boundary $token");
            }
            foreach (array('chargeUser(', 'chargeVendor(', 'bc_fintech_ledger_post(', 'UPDATE sas_') as $token) {
                chk(strpos($cur, $token) === false, "$label cannot move funds via $token");
            }
            continue;
        }

        if ($name === 'Receive.php') {
            foreach (array('bc_app_sidebar(', 'bc-fintech-flutterwave.php', 'bc_validate_csrf();', "bc_is_rate_limited('invoice_create'", 'sas_secure_payment_intents', 'bc_flw_create_payment_link($vid,', '/web/InvoiceReturn.php', 'bc_csrf_field()', 'htmlspecialchars($url,ENT_QUOTES,', 'rawurlencode($email)') as $token) {
                chk(strpos($cur, $token) !== false, "$label keeps invoice boundary $token");
            }
            chk(strpos($cur, 'bc_validate_csrf();') < strpos($cur, 'bc_flw_create_payment_link('), "$label verifies CSRF before provider calls");
            chk(strpos($cur, 'sas_secure_payment_intents') < strpos($cur, 'bc_flw_create_payment_link('), "$label binds intent before provider calls");
            foreach (array('chargeUser(', 'chargeVendor(', 'bc_fintech_ledger_post(', 'updateUserBalance(') as $token) {
                chk(strpos($cur, $token) === false, "$label cannot directly credit via $token");
            }
            continue;
        }

        if ($name === 'handle_upgrade.php') {
            foreach (array('bc_app_sidebar(', 'bc-paid-entitlements.php', 'bc-paid-security.php', 'bc_validate_csrf();', 'bc_paid_verify(', 'bc_paid_level_change(', 'name="expected_level"', 'name="paid_quote"', 'data-paid-save', 'bc_paid_fields(', 'bc_paid_otp_script();', 'Business access requires KYB review') as $token) {
                chk(strpos($cur, $token) !== false, "$label keeps paid level boundary $token");
            }
            chk(strpos($cur, 'bc_paid_verify(') < strpos($cur, 'bc_paid_level_change('), "$label verifies before charging");
            chk(strpos($cur, 'UPDATE sas_users') === false && strpos($cur, 'chargeUser(') === false, "$label delegates atomic changes");
            continue;
        }

        // §28: ViewCryptoInvoice.php became read-only history — it displays the
        // stored invoice and never contacts a provider (no regeneration, sync or
        // live fetch), so its PHP changed legitimately. Pin the new contract.
        if ($name === 'ViewCryptoInvoice.php') {
            chk(strpos($cur, 'bc_app_sidebar(') !== false, "$label uses the shell sidebar");
            chk(strpos($cur, 'createPlisioInvoice') === false && strpos($cur, 'getPlisioTransactionDetails') === false && strpos($cur, 'getPlisioPublicInvoice') === false, "$label calls no retired-provider functions");
            chk(strpos($cur, 'can no longer be regenerated') !== false, "$label refuses invoice regeneration");
            continue;
        }

        if (in_array($rel, $handDone, true)) {
            chk(strpos($cur, 'bc_app_sidebar(') !== false, "$label uses the shell sidebar");
            continue;
        }

        chk(isset($before['VTU/' . $rel]), "$label is in the captured set");
        if (!isset($before['VTU/' . $rel])) continue;
        chk(strpos($cur, $before['VTU/' . $rel]) !== false, "$label body is unchanged");
        chk(substr_count($cur, 'short-trans.php') === substr_count($before['VTU/' . $rel], 'short-trans.php'),
            "$label keeps its short-trans partial");
    }
}

echo "plate_migration_test: $checks checks\n";
